          starter: "from functools import lru_cache\n\n\n@lru_cache(maxsize=None)\ndef count_ways(coins, amount, i=0):\n    if amount == 0:\n        return 1\n    if amount < 0 or i == len(coins):\n        return 0\n    return count_ways(coins, amount - coins[i], i) + count_ways(coins, amount, i + 1)\n\n\ncoins = [int(t) for t in input().split()]\namount = int(input())\nprint(count_ways(coins, amount), \"วิธี\")\n", xp: 60,
