          desc: "ฟังก์ชันสำคัญที่สุดของระบบต้องมี test คุม — เขียน test ใน <code>TestPlaceOrder</code> สำหรับ <code>place_order</code> (จาก C4) อย่างน้อย 3 test โดยใช้ <code>setUp</code> สร้างคลังใหม่ทุกครั้ง (<code>make_inventory()</code>: BK-001 = 5 · PN-002 = 2) · ระบบรัน test ของคุณกับเวอร์ชันที่ถูกต้องและเวอร์ชันที่มีบั๊กซ่อนอยู่หลายแบบ — คิดว่าคุณสมบัติสำคัญของ place_order มีอะไรบ้าง: ตัดถูกจำนวน · ล้มเหลวแล้วต้องไม่ตัดอะไรเลย · รหัสซ้ำต้องรวมจำนวน", goal: "test ผ่านกับเวอร์ชันถูกต้อง และจับเวอร์ชันที่มีบั๊กได้ทุกแบบ",
          starter: "import io\nimport unittest\nfrom dataclasses import dataclass\nfrom decimal import Decimal\nimport re\n\nSKU_PATTERN = re.compile(r\"[A-Z]{2}-\\d{3}\")\n\n\n@dataclass(frozen=True)\nclass Product:\n    sku: str\n    name: str\n    price: Decimal\n\n    def __post_init__(self):\n        if not SKU_PATTERN.fullmatch(self.sku):\n            raise ValueError(f\"รหัสสินค้าไม่ถูกต้อง: {self.sku}\")\n        if not self.name.strip():\n            raise ValueError(\"ชื่อสินค้าว่าง\")\n        if self.price <= 0:\n            raise ValueError(\"ราคาต้องมากกว่า 0\")\n\n\nclass ShopError(Exception):\n    pass\n\n\nclass NotFoundError(ShopError):\n    pass\n\n\nclass OutOfStockError(ShopError):\n    pass\n\n\nclass Inventory:\n    def __init__(self):\n        self._products = {}\n        self._stock = {}\n\n    def add(self, product, qty):\n        if qty < 0:\n            raise ValueError(\"จำนวนต้องไม่ติดลบ\")\n        self._products[product.sku] = product\n        self._stock[product.sku] = self._stock.get(product.sku, 0) + qty\n\n    def product(self, sku):\n        if sku not in self._products:\n            raise NotFoundError(f\"ไม่พบสินค้า {sku}\")\n        return self._products[sku]\n\n    def stock(self, sku):\n        self.product(sku)\n        return self._stock[sku]\n\n    def remove(self, sku, qty):\n        available = self.stock(sku)\n        if qty > available:\n            raise OutOfStockError(f\"{sku} เหลือ {available}\")\n        self._stock[sku] = available - qty\n\n    def skus(self):\n        return sorted(self._products)\n\n\ndef place_order_ok(inventory, items):\n    needed = {}\n    for sku, qty in items:\n        needed[sku] = needed.get(sku, 0) + qty\n    shortages = [sku for sku, qty in needed.items() if qty > inventory.stock(sku)]\n    if shortages:\n        raise OutOfStockError(\"สินค้าไม่พอ: \" + \", \".join(sorted(shortages)))\n    for sku, qty in needed.items():\n        inventory.remove(sku, qty)\n\n\ndef place_order_m1(inventory, items):\n    for sku, qty in items:\n        inventory.remove(sku, qty)\n\n\ndef place_order_m2(inventory, items):\n    for sku, qty in items:\n        if qty > inventory.stock(sku):\n            raise OutOfStockError(\"สินค้าไม่พอ: \" + sku)\n    for sku, qty in items:\n        inventory.remove(sku, qty)\n\n\ndef place_order_m3(inventory, items):\n    needed = {}\n    for sku, qty in items:\n        needed[sku] = needed.get(sku, 0) + qty\n    shortages = [sku for sku, qty in needed.items() if qty > inventory.stock(sku)]\n    if shortages:\n        raise OutOfStockError(\"สินค้าไม่พอ: \" + \", \".join(sorted(shortages)))\n    for sku in needed:\n        inventory.remove(sku, 1)\n\n\nVARIANTS = {\"ok\": place_order_ok, \"m1\": place_order_m1, \"m2\": place_order_m2, \"m3\": place_order_m3}\n\nmode = input()\nplace_order = VARIANTS[mode]\n\n\ndef make_inventory():\n    inv = Inventory()\n    inv.add(Product(\"BK-001\", \"สมุด\", Decimal(\"25\")), 5)\n    inv.add(Product(\"PN-002\", \"ปากกา\", Decimal(\"12\")), 2)\n    return inv\n\n\nclass TestPlaceOrder(unittest.TestCase):\n    def setUp(self):\n        self.inv = make_inventory()\n\n    # เขียน test ตรงนี้ (ใช้ place_order และ self.inv)\n\n\nsuite = unittest.defaultTestLoader.loadTestsFromTestCase(TestPlaceOrder)\nresult = unittest.TextTestRunner(stream=io.StringIO(), verbosity=0).run(suite)\nprint(\"ผ่าน\" if result.wasSuccessful() and result.testsRun > 0 else \"ล้มเหลว\")\n", xp: 100,
          hints: ["test หนึ่งตัวต่อหนึ่งคุณสมบัติ · ตรวจสต็อกหลังเรียกด้วย assertEqual", "กรณีล้มเหลว: ใช้ assertRaises แล้วตรวจต่อว่าสต็อกของรายการที่พอ<b>ไม่ถูกตัด</b>", "รหัสซ้ำ: [(\"PN-002\", 2), (\"PN-002\", 1)] รวมเป็น 3 ซึ่งเกินที่มี"],
