          starter: "import json\nimport re\nfrom dataclasses import dataclass, field\nfrom http import HTTPStatus\nfrom urllib.parse import parse_qs\n\n\n@dataclass\nclass Request:\n    method: str\n    path: str\n    query: dict = field(default_factory=dict)\n    body: str = \"\"\n\n    def json(self):\n        return json.loads(self.body)\n\n\ndef make_request(environ):\n    length = int(environ.get(\"CONTENT_LENGTH\") or 0)\n    body = environ[\"wsgi.input\"].read(length).decode(\"utf-8\")\n    query = {k: v[0] for k, v in parse_qs(environ[\"QUERY_STRING\"]).items()}\n    return Request(environ[\"REQUEST_METHOD\"], environ[\"PATH_INFO\"], query, body)\n\n\ndef send(start_response, code, payload, extra_headers=()):\n    status = f\"{code} {HTTPStatus(code).phrase}\"\n    if payload is None:\n        start_response(status, list(extra_headers))\n        return []\n    body = json.dumps(payload, ensure_ascii=False).encode(\"utf-8\")\n    start_response(status, [(\"Content-Type\", \"application/json; charset=utf-8\"), *extra_headers])\n    return [body]\n\n\ndef compile_path(path):\n    \"\"\"แปลง /users/<id> เป็น regex ^/users/(?P<id>[^/]+)$\"\"\"\n    return re.compile(\"^\" + re.sub(r\"<(\\w+)>\", r\"(?P<\\1>[^/]+)\", path) + \"$\")\n\n\nclass App:\n    def __init__(self):\n        self.routes = []\n\n    def route(self, path, methods=(\"GET\",)):\n        def register(handler):\n            self.routes.append((path, compile_path(path), {m.upper() for m in methods}, handler))\n            return handler\n        return register\n\n    def _candidates(self, path):\n        for raw, pattern, methods, handler in self.routes:\n            match = pattern.match(path)\n            if match:\n                yield methods, handler, match.groupdict()\n\n    def __call__(self, environ, start_response):\n        req = make_request(environ)\n        allowed = set()\n        for methods, handler, params in self._candidates(req.path):\n            if req.method in methods:\n                try:\n                    code, payload = handler(req, **params)\n                except json.JSONDecodeError:\n                    return send(start_response, 400, {\"error\": \"JSON ไม่ถูกต้อง\"})\n                return send(start_response, code, payload)\n            allowed |= methods\n        if allowed:\n            return send(start_response, 405, {\"error\": \"ใช้ method นี้ไม่ได้\"}, [(\"Allow\", \", \".join(sorted(allowed)))])\n        return send(start_response, 404, {\"error\": f\"ไม่พบ {req.path}\"})\n\n\napp = App()\n\n\n@app.route(\"/users/<user_id>\")\ndef user(req, user_id):\n    return 200, {\"user\": user_id}\n\n\n@app.route(\"/users/me\")\ndef me(req):\n    return 200, {\"profile\": \"บัญชีของฉัน\"}\n\n\nimport io\nimport json\nfrom wsgiref.util import setup_testing_defaults\n\n\ndef call(app, method, path, body=\"\", headers=None):\n    \"\"\"ส่งคำขอจำลองให้แอป WSGI โดยไม่ต้องมีเครือข่าย แล้วคืน (status, headers, body)\"\"\"\n    path, _, query = path.partition(\"?\")\n    data = body.encode(\"utf-8\")\n    environ = {\"REQUEST_METHOD\": method, \"PATH_INFO\": path, \"QUERY_STRING\": query,\n               \"CONTENT_LENGTH\": str(len(data)), \"wsgi.input\": io.BytesIO(data)}\n    for name, value in (headers or {}).items():\n        environ[\"HTTP_\" + name.upper().replace(\"-\", \"_\")] = value\n    setup_testing_defaults(environ)\n    captured = {}\n\n    def start_response(status, response_headers):\n        captured[\"status\"] = status\n        captured[\"headers\"] = dict(response_headers)\n\n    chunks = app(environ, start_response)\n    return captured[\"status\"], captured[\"headers\"], b\"\".join(chunks).decode(\"utf-8\")\n\n\nwhile (line := input()) != \"end\":\n    parts = line.split(\" \", 2)\n    method, path = parts[0], parts[1]\n    body = parts[2] if len(parts) > 2 else \"\"\n    status, headers, text = call(app, method, path, body)\n    extra = f\" | Allow: {headers['Allow']}\" if \"Allow\" in headers else \"\"\n    print(f\"{status} | {headers.get('Content-Type', '-')} | {text}{extra}\")\n", xp: 60,
